WITH src AS (SELECT * FROM accounts WHERE status IN ('OPEN', 'FROZEN')), opened_year_summary AS (SELECT YEAR(opened_date) AS opened_year, status, ROUND((100 * SUM(CASE WHEN status = 'OPEN' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_open FROM src GROUP BY YEAR(opened_date), status) SELECT opened_year, status, pct_open FROM opened_year_summary WHERE pct_open > 50 ORDER BY status, opened_year LIMIT 20;
